import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import type { HeroProps } from "@generated/designer/sections.hero"

const pad = { display: "py-24 md:py-32", default: "py-16 md:py-24", compact: "py-10 md:py-14" } as const
const heading = { display: "text-4xl md:text-6xl", default: "text-3xl md:text-5xl", compact: "text-2xl md:text-4xl" } as const

export function Hero({ copy, variant, actions, media }: HeroProps) {
  const split = variant.layout === "split" && media
  const bleed = variant.layout === "full-bleed" && media
  return (
    <section
      data-slot="hero"
      data-layout={variant.layout}
      className={cn(
        "relative isolate overflow-hidden",
        variant.ground === "inverse" ? "bg-primary text-primary-foreground" : "bg-background text-foreground",
      )}
    >
      {bleed && media ? (
        <img src={media.asset.src} alt={copy.media?.alt ?? ""} width={media.asset.width} height={media.asset.height}
          className="absolute inset-0 -z-10 size-full object-cover" />
      ) : null}
      {bleed && variant.backdrop !== "none" ? (
        <div aria-hidden className={cn("absolute inset-0 -z-10 bg-background", variant.backdrop === "scrim.strong" ? "opacity-80" : "opacity-50")} />
      ) : null}
      <div className={cn("mx-auto grid max-w-6xl gap-10 px-6", pad[variant.size], split && "md:grid-cols-2 md:items-center")}>
        <div className={cn("flex flex-col items-start gap-6", variant.layout === "editorial" && "max-w-3xl")}>
          {copy.header.eyebrow ? <Badge variant="secondary">{copy.header.eyebrow}</Badge> : null}
          <h1 className={cn("text-balance font-semibold tracking-tight", heading[variant.size])}>{copy.header.heading}</h1>
          {copy.header.description ? (
            <p className="max-w-2xl text-pretty text-lg opacity-80">{copy.header.description}</p>
          ) : null}
          <div className="flex flex-wrap gap-3">
            {copy.actions?.primary && actions?.primary ? (
              <Button asChild size="lg"><a href={actions.primary.href}>{copy.actions.primary.label}</a></Button>
            ) : null}
            {copy.actions?.secondary && actions?.secondary ? (
              <Button asChild size="lg" variant="outline"><a href={actions.secondary.href}>{copy.actions.secondary.label}</a></Button>
            ) : null}
          </div>
        </div>
        {split && media ? (
          <img src={media.asset.src} alt={copy.media?.alt ?? ""} width={media.asset.width} height={media.asset.height}
            className="w-full rounded-xl border object-cover" />
        ) : null}
      </div>
    </section>
  )
}
